package com.example.mxb.storage;

import org.bukkit.plugin.java.JavaPlugin;

import java.io.File;
import java.sql.*;
import java.util.logging.Level;

public class Database {

    private final JavaPlugin plugin;
        private Connection connection;

            public Database(JavaPlugin plugin) {
                    this.plugin = plugin;
                        }

                            public void init() {
                                    try {
                                                File folder = plugin.getDataFolder();
                                                            if (!folder.exists()) folder.mkdirs();

                                                                        File dbFile = new File(folder, "mxb.db");
                                                                                    connection = DriverManager.getConnection("jdbc:sqlite:" + dbFile.getAbsolutePath());

                                                                                                try (Statement st = connection.createStatement()) {
                                                                                                                st.executeUpdate("""
                                                                                                                                    CREATE TABLE IF NOT EXISTS bans (
                                                                                                                                                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                                                                                                                                                                                    uuid TEXT NOT NULL,
                                                                                                                                                                                                            name TEXT NOT NULL,
                                                                                                                                                                                                                                    ip TEXT,
                                                                                                                                                                                                                                                            reason TEXT,
                                                                                                                                                                                                                                                                                    cheat_type TEXT,
                                                                                                                                                                                                                                                                                                            cheat_type_name TEXT,
                                                                                                                                                                                                                                                                                                                                    start_time INTEGER,
                                                                                                                                                                                                                                                                                                                                                            end_time INTEGER,
                                                                                                                                                                                                                                                                                                                                                                                    operator_uuid TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                            operator_name TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                    active INTEGER DEFAULT 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            unbanned_by_uuid TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    unbanned_by_name TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            unban_time INTEGER,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    unban_reason TEXT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        """);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        st.executeUpdate("""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CREATE TABLE IF NOT EXISTS warn_records (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            uuid TEXT NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name TEXT NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ip TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cheat_type TEXT NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cheat_type_name TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    operator_uuid TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            operator_name TEXT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    time INTEGER,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            resulted_in_ban INTEGER DEFAULT 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                """);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                st.executeUpdate("""
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    CREATE TABLE IF NOT EXISTS warn_counts (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            uuid TEXT NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cheat_type TEXT NOT NULL,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            count INTEGER DEFAULT 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    PRIMARY KEY (uuid, cheat_type)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        """);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        st.executeUpdate("CREATE INDEX IF NOT EXISTS idx_bans_uuid ON bans(uuid)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        st.executeUpdate("CREATE INDEX IF NOT EXISTS idx_bans_active ON bans(active)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        st.executeUpdate("CREATE INDEX IF NOT EXISTS idx_warn_records_uuid ON warn_records(uuid)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                plugin.getLogger().info("SQLite 数据库已就绪");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    plugin.getLogger().log(Level.SEVERE, "数据库初始化失败", e);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    public synchronized Connection getConnection() { return connection; }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        public synchronized void close() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (connection != null && !connection.isClosed()) connection.close();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (SQLException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                e.printStackTrace();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }